    r0 = BLK_CHAIN_B;
    r9 = r0 + r1;
    call _gate_pair_blk;
    rts;

.dgs_31_32:
    /* scalar fallback, squared up to B-in/B-out per pool */
    call _C1_GATE_31_process;          /* B_P1 -> A_P1 */
    l3 = 0; l4 = 0;
    i3 = BLK_CHAIN_A_P1;
    i4 = BLK_CHAIN_B_P1;
    lcntr = DSP4_BLOCK_SIZE, do .dgs_c1_31_32 until lce;
        r0 = dm(i3, 1);
    .dgs_c1_31_32: dm(i4, 1) = r0;
    call _C1_GATE_32_process;          /* B -> A */
    i3 = BLK_CHAIN_A;
    i4 = BLK_CHAIN_B;
    lcntr = DSP4_BLOCK_SIZE, do .dgs_c2_31_32 until lce;
        r0 = dm(i3, 1);
    .dgs_c2_31_32: dm(i4, 1) = r0;
    rts;
_DYNGATE_31_32_process.end:

/* ---- strips 31 + 32: COMP ---- */
.global _DYNCOMP_31_32_process;
_DYNCOMP_31_32_process:
    r0 = dm(_comp_on_C1_COMP_31);
    r0 = pass r0;
    if eq jump (pc, .dcs_31_32);
    r0 = dm(_comp_on_C1_COMP_32);
    r0 = pass r0;
    if eq jump (pc, .dcs_31_32);

    r5 = dm(_sample_idx);
    dm(_dynpair_saved_idx) = r5;
    r5 = 0;
    dm(_sample_idx) = r5;
    r0 = dm(BLK_CHAIN_B_P1);
    dm(_buf_C1_GATE_31) = r0;
    call _C1_COMP_31_process_sample;
    r0 = dm(_buf_C1_COMP_31);
    dm(BLK_CHAIN_B_P1) = r0;
    r0 = dm(BLK_CHAIN_B);
    dm(_buf_C1_GATE_32) = r0;
    call _C1_COMP_32_process_sample;
    r0 = dm(_buf_C1_COMP_32);
    dm(BLK_CHAIN_B) = r0;
    r5 = dm(_dynpair_saved_idx);
    dm(_sample_idx) = r5;

    r0 = DSP4_BLOCK_SIZE-1;
    dm(_dsim_n) = r0;
    dm(_dsim_n + 1) = r0;
    r4 = _comp_attq_C1_COMP_31;        /* attq relq mkq parq thr slope halfk k2 */
    r5 = _comp_attq_C1_COMP_32;
    r6 = _comp_envelope_C1_COMP_31;
    r7 = _comp_envelope_C1_COMP_32;
    r0 = BLK_CHAIN_B_P1;
    r1 = 1;
    r8 = r0 + r1;
    r0 = BLK_CHAIN_B;
    r9 = r0 + r1;
    call _comp_pair_blk;
    /* the pair writes its gain display to the shared park; give it
     * back to each node so dsp4_dyn_witness.py still reads a live
     * per-strip compressor gain. */
    i0 = _cmp_gn;
    r0 = dm(i0, 1);
    dm(_comp_gain_C1_COMP_31) = r0;
    r0 = dm(i0, 1);
    dm(_comp_gain_C1_COMP_32) = r0;
    rts;

.dcs_31_32:
    /* scalar fallback, squared up to B-in/B-out per pool */
    l3 = 0; l4 = 0;
    i3 = BLK_CHAIN_B_P1;
    i4 = BLK_CHAIN_A_P1;
    lcntr = DSP4_BLOCK_SIZE, do .dcs_c1_31_32 until lce;
        r0 = dm(i3, 1);
    .dcs_c1_31_32: dm(i4, 1) = r0;
    call _C1_COMP_31_process;          /* A_P1 -> B_P1 */
    i3 = BLK_CHAIN_B;
    i4 = BLK_CHAIN_A;
    lcntr = DSP4_BLOCK_SIZE, do .dcs_c2_31_32 until lce;
        r0 = dm(i3, 1);
    .dcs_c2_31_32: dm(i4, 1) = r0;
    call _C1_COMP_32_process;          /* A -> B */
    rts;
_DYNCOMP_31_32_process.end:

#if DSP4_GATE_LINTHR
#error "DSP4_SIMD_DYN pairs the GATE in the log2 domain; DSP4_GATE_LINTHR converts the threshold to linear once per block and the two are different arithmetic. Build with DSP4_GATE_LINTHR=0."
#endif
#if !DSP4_BLOCK_KERNELS
#error "DSP4_SIMD_GRAPH is a per-BLOCK pairing: build with DSP4_BLOCK_KERNELS=1."
#endif

#endif /* DSP4_PAIRED_GRAPH */
